begin;
create table if not exists public.role_module_permissions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,role_id uuid not null references public.roles(id) on delete cascade,module text not null,can_view boolean not null default false,can_create boolean not null default false,can_edit boolean not null default false,can_approve boolean not null default false,can_delete boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,role_id,module));
create table if not exists public.member_restaurant_access(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,company_member_id uuid not null references public.company_members(id) on delete cascade,restaurant_id uuid not null references public.restaurants(id) on delete cascade,access_level text not null default 'standard' check(access_level in('read','standard','manager')),created_at timestamptz not null default now(),unique(company_member_id,restaurant_id));
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,restaurant_id uuid references public.restaurants(id) on delete set null,user_id uuid,action text not null,module text not null,entity_type text,entity_id uuid,summary text,metadata jsonb not null default '{}'::jsonb,ip_hash text,created_at timestamptz not null default now());
create table if not exists public.security_settings(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,session_timeout_minutes integer not null default 480,password_min_length integer not null default 10,require_mfa_for_admins boolean not null default false,audit_retention_days integer not null default 365,allow_support_access boolean not null default false,updated_at timestamptz not null default now(),unique(company_id));
create table if not exists public.user_session_activity(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null,device_label text,browser text,last_active_at timestamptz not null default now(),signed_in_at timestamptz not null default now(),revoked_at timestamptz);
create index if not exists role_permissions_lookup_idx on public.role_module_permissions(company_id,role_id,module);create index if not exists member_restaurant_lookup_idx on public.member_restaurant_access(company_member_id,restaurant_id);create index if not exists audit_logs_company_date_idx on public.audit_logs(company_id,created_at desc);create index if not exists sessions_company_active_idx on public.user_session_activity(company_id,last_active_at desc);
alter table public.role_module_permissions enable row level security;alter table public.member_restaurant_access enable row level security;alter table public.audit_logs enable row level security;alter table public.security_settings enable row level security;alter table public.user_session_activity enable row level security;
do $$ declare t text;begin foreach t in array array['role_module_permissions','member_restaurant_access','audit_logs','security_settings','user_session_activity'] loop execute format('drop policy if exists company_members_access on public.%I',t);execute format('create policy company_members_access on public.%I for all to authenticated using(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid())) with check(exists(select 1 from public.company_members cm where cm.company_id=%I.company_id and cm.user_id=auth.uid()))',t,t,t);end loop;end $$;
grant select,insert,update,delete on public.role_module_permissions,public.member_restaurant_access,public.audit_logs,public.security_settings,public.user_session_activity to authenticated;
do $$ declare c uuid;r uuid;owner_role uuid;manager_role uuid;employee_role uuid;begin select id into c from public.companies order by created_at limit 1;select id into r from public.restaurants where company_id=c order by created_at limit 1;select id into owner_role from public.roles where code='owner' limit 1;select id into manager_role from public.roles where code='manager' limit 1;select id into employee_role from public.roles where code='employee' limit 1;if c is not null then insert into public.security_settings(company_id) values(c) on conflict(company_id) do nothing;if owner_role is not null then insert into public.role_module_permissions(company_id,role_id,module,can_view,can_create,can_edit,can_approve,can_delete) select c,owner_role,m,true,true,true,true,true from unnest(array['dashboard','people','schedule','operations','purchases','inventory','profitability','customers','cash','billing','integrations','settings']) m on conflict(company_id,role_id,module) do nothing;end if;if manager_role is not null then insert into public.role_module_permissions(company_id,role_id,module,can_view,can_create,can_edit,can_approve,can_delete) select c,manager_role,m,true,true,true,true,false from unnest(array['dashboard','people','schedule','operations','purchases','inventory','profitability','customers','cash']) m on conflict(company_id,role_id,module) do nothing;end if;if employee_role is not null then insert into public.role_module_permissions(company_id,role_id,module,can_view) select c,employee_role,m,true from unnest(array['dashboard','schedule']) m on conflict(company_id,role_id,module) do nothing;end if;insert into public.audit_logs(company_id,restaurant_id,action,module,entity_type,summary) select c,r,'login','security','session','Inicio de sesión correcto' where not exists(select 1 from public.audit_logs where company_id=c and summary='Inicio de sesión correcto');end if;end $$;
commit;
